const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

// Secure configuration
const JWT_SECRET = crypto.randomBytes(64);
const RATE_LIMIT_WINDOW = 60000;
const RATE_LIMIT_MAX = 100;
const MAX_BODY_SIZE = 4096;

// In-memory stores
const users = new Map();
const sessions = new Map();
const rateLimits = new Map();
const transactionLog = [];

// Security utilities
function safeCompare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(Buffer.from(a), Buffer.from(b));
}

function hashPassword(password, salt) {
  salt = salt || crypto.randomBytes(32).toString('hex');
  const hash = crypto.pbkdf2Sync(password, salt, 310000, 64, 'sha512').toString('hex');
  return { hash, salt };
}

function generateToken(userId) {
  const payload = { sub: userId, iat: Date.now(), exp: Date.now() + 3600000, jti: crypto.randomUUID() };
  const header = Buffer.from(JSON.stringify({alg:'HS256',typ:'JWT'})).toString('base64url');
  const body = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const sig = crypto.createHmac('sha256', JWT_SECRET).update(`${header}.${body}`).digest('base64url');
  return `${header}.${body}.${sig}`;
}

function verifyToken(token) {
  if (typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 3) return null;
  const [header, body, sig] = parts;
  const expectedSig = crypto.createHmac('sha256', JWT_SECRET).update(`${header}.${body}`).digest('base64url');
  if (!safeCompare(sig, expectedSig)) return null;
  try {
    const payload = JSON.parse(Buffer.from(body, 'base64url').toString());
    if (typeof payload.exp !== 'number' || payload.exp < Date.now()) return null;
    if (typeof payload.sub !== 'string') return null;
    return payload;
  } catch { return null; }
}

function checkRateLimit(ip) {
  const now = Date.now();
  const record = rateLimits.get(ip) || { count: 0, resetAt: now + RATE_LIMIT_WINDOW };
  if (now > record.resetAt) { record.count = 0; record.resetAt = now + RATE_LIMIT_WINDOW; }
  record.count++;
  rateLimits.set(ip, record);
  return record.count <= RATE_LIMIT_MAX;
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    let size = 0;
    req.on('data', chunk => {
      size += chunk.length;
      if (size > MAX_BODY_SIZE) { req.destroy(); reject(new Error('too large')); return; }
      data += chunk;
    });
    req.on('end', () => {
      try { resolve(JSON.parse(data)); } catch { reject(new Error('invalid json')); }
    });
    req.on('error', reject);
  });
}

function authenticate(req) {
  const auth = req.headers['authorization'];
  if (!auth || !auth.startsWith('Bearer ')) return null;
  return verifyToken(auth.slice(7));
}

// Account operations with mutex-based concurrency control
class AccountService {
  constructor() {
    this.locks = new Map();
    this.minimumBalance = 0;
  }

  getAccount(userId) {
    return users.get(userId);
  }

  validateAmount(amount) {
    if (typeof amount !== 'number') return false;
    if (!Number.isFinite(amount)) return false;
    if (amount <= 0) return false;
    if (amount > 1000000) return false;
    if (Math.round(amount * 100) !== amount * 100) return false;
    return true;
  }

  toCents(amount) {
    return Math.round(amount * 100);
  }

  // Acquire per-user lock to prevent race conditions
  async acquireLock(userId) {
    while (this.locks.get(userId)) {
      await new Promise(resolve => setImmediate(resolve));
    }
    this.locks.set(userId, true);
  }

  releaseLock(userId) {
    this.locks.delete(userId);
  }

  // Process withdrawal with lock held throughout
  async processWithdrawal(userId, amount) {
    if (!this.validateAmount(amount)) {
      return { success: false, error: 'invalid_amount' };
    }

    const amountCents = this.toCents(amount);

    // Acquire lock before checking balance
    await this.acquireLock(userId);
    try {
      const account = this.getAccount(userId);
      if (!account) return { success: false, error: 'account_not_found' };

      // Check balance under lock
      const availableBalance = account.balanceCents - this.minimumBalance;
      if (availableBalance < amountCents) {
        return { success: false, error: 'insufficient_funds' };
      }

      // Deduct immediately under lock - no await between check and deduct
      account.balanceCents -= amountCents;

      const txn = {
        id: crypto.randomUUID(),
        userId,
        type: 'withdrawal',
        amountCents,
        balanceAfter: account.balanceCents,
        timestamp: Date.now()
      };
      transactionLog.push(txn);

      return { success: true, transaction: txn };
    } finally {
      this.releaseLock(userId);
    }
  }

  // Process deposit with lock
  async processDeposit(userId, amount) {
    if (!this.validateAmount(amount)) {
      return { success: false, error: 'invalid_amount' };
    }

    const amountCents = this.toCents(amount);

    await this.acquireLock(userId);
    try {
      const account = this.getAccount(userId);
      if (!account) return { success: false, error: 'account_not_found' };

      account.balanceCents += amountCents;

      const txn = {
        id: crypto.randomUUID(),
        userId,
        type: 'deposit',
        amountCents,
        balanceAfter: account.balanceCents,
        timestamp: Date.now()
      };
      transactionLog.push(txn);

      return { success: true, transaction: txn };
    } finally {
      this.releaseLock(userId);
    }
  }
}

const accountService = new AccountService();

// Request handlers
async function handleRegister(req, res) {
  const body = await parseBody(req);
  const { username, password } = body;

  if (typeof username !== 'string' || typeof password !== 'string') {
    res.writeHead(400, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'invalid_input'}));
  }
  if (!/^[a-zA-Z0-9_]{3,20}$/.test(username)) {
    res.writeHead(400, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'invalid_username'}));
  }
  if (password.length < 8 || password.length > 72) {
    res.writeHead(400, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'invalid_password'}));
  }
  if (users.has(username)) {
    res.writeHead(409, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'user_exists'}));
  }

  const { hash, salt } = hashPassword(password);
  users.set(username, { username, hash, salt, balanceCents: 10000, role: 'user', createdAt: Date.now() });

  res.writeHead(201, {'Content-Type':'application/json'});
  res.end(JSON.stringify({success:true}));
}

async function handleLogin(req, res) {
  const body = await parseBody(req);
  const { username, password } = body;

  if (typeof username !== 'string' || typeof password !== 'string') {
    res.writeHead(400, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'invalid_input'}));
  }

  const user = users.get(username);
  const dummySalt = crypto.randomBytes(32).toString('hex');
  const { hash } = user ? hashPassword(password, user.salt) : hashPassword(password, dummySalt);

  if (!user || !safeCompare(hash, user.hash)) {
    res.writeHead(401, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'invalid_credentials'}));
  }

  const token = generateToken(username);
  sessions.set(username, { token, lastActivity: Date.now() });

  res.writeHead(200, {'Content-Type':'application/json'});
  res.end(JSON.stringify({token}));
}

async function handleWithdraw(req, res) {
  const payload = authenticate(req);
  if (!payload) {
    res.writeHead(401, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'unauthorized'}));
  }

  const body = await parseBody(req);
  const { amount } = body;

  const result = await accountService.processWithdrawal(payload.sub, amount);

  if (!result.success) {
    res.writeHead(400, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error: result.error}));
  }

  res.writeHead(200, {'Content-Type':'application/json'});
  res.end(JSON.stringify({success: true, transaction: result.transaction}));
}

async function handleDeposit(req, res) {
  const payload = authenticate(req);
  if (!payload) {
    res.writeHead(401, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'unauthorized'}));
  }

  const body = await parseBody(req);
  const { amount } = body;

  const result = await accountService.processDeposit(payload.sub, amount);

  if (!result.success) {
    res.writeHead(400, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error: result.error}));
  }

  res.writeHead(200, {'Content-Type':'application/json'});
  res.end(JSON.stringify({success: true, transaction: result.transaction}));
}

async function handleBalance(req, res) {
  const payload = authenticate(req);
  if (!payload) {
    res.writeHead(401, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'unauthorized'}));
  }

  const account = accountService.getAccount(payload.sub);
  if (!account) {
    res.writeHead(404, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'not_found'}));
  }

  res.writeHead(200, {'Content-Type':'application/json'});
  res.end(JSON.stringify({balance: account.balanceCents / 100, balanceCents: account.balanceCents}));
}

// Server setup
const server = http.createServer(async (req, res) => {
  const ip = req.socket.remoteAddress;
  if (!checkRateLimit(ip)) {
    res.writeHead(429, {'Content-Type':'application/json'});
    return res.end(JSON.stringify({error:'rate_limited'}));
  }

  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Cache-Control', 'no-store');

  const url = new URL(req.url, `http://${req.headers.host}`);

  try {
    if (url.pathname === '/api/register' && req.method === 'POST') {
      await handleRegister(req, res);
    } else if (url.pathname === '/api/login' && req.method === 'POST') {
      await handleLogin(req, res);
    } else if (url.pathname === '/api/withdraw' && req.method === 'POST') {
      await handleWithdraw(req, res);
    } else if (url.pathname === '/api/deposit' && req.method === 'POST') {
      await handleDeposit(req, res);
    } else if (url.pathname === '/api/balance' && req.method === 'GET') {
      await handleBalance(req, res);
    } else {
      res.writeHead(404, {'Content-Type':'application/json'});
      res.end(JSON.stringify({error:'not_found'}));
    }
  } catch (err) {
    if (!res.headersSent) {
      res.writeHead(500, {'Content-Type':'application/json'});
      res.end(JSON.stringify({error:'internal_error'}));
    }
  }
});

server.listen(3000);
